/**
 * The Assyrian Shadow
 * -------------------
 * The Assyrian advances like a river, and the surviving stump of Jesse stands as a banner for the peoples. Stage: a great army crossing a plain, a felled tree with a living shoot, a banner raised on a hill; a dark flood of bronze and a single green branch.
 *
 * Palette 0x241810 → 0x060402 · light: dusk · hero: tree
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./isaiah-kit.js.
 */

import { THREE, createScene, water, oak, army, person, birds } from './isaiah-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3087180171, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x020101, 0x070502);
    W.ground(260, 95, 0, 60, 0x060402, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x050302, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, -14.6]);

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x050302), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* trees: broadleaf shade */
    oak(W, group, -22.4, 0, -42.8, 1.23, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -74.9, 0, 0.4, 1.12, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -72.6, 0, -4.2, 1.18, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* army: shields and spears in rank */
    army(W, group, -14.7, 23.0, 8, { shields: [0x17100a, 0x050402, 0x8a7a2a, 0x3a5a8a] });

    /* hero: the great tree */
    oak(W, group, 0, 0, 11, 1.7, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    W.disc([0, 8, -5], 9, 0x2f1f15, 0.25);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0x241810, bend: 0.2, armR: [0.35, 0.1], armL: [-0.35, -0.1], ry: 0.13, s: 1.02 });

    /* birds: slow circles high above */
    birds(W, group, 6, 55, { y: 26 });

    return W.finish();
}

export default { build };
